import { sql } from 'drizzle-orm';
import { check, pgTable, smallint, text, timestamp, uniqueIndex, uuid } from 'drizzle-orm/pg-core';
import { tenants } from './tenants';

/**
 * Phase 09.1-05 (D-486, PAY-04): a tenant's connection to ONE payment gateway. The INTEGRATION ROW is
 * the primary noun of the seam, not the environment: `provider` names the adapter that verifies and
 * normalises this tenant's deliveries (`packages/core/server/payments/adapters.ts`), so two tenants can
 * sit on two different gateways with no rewrite.
 *
 * `id` is generated by the APPLICATION before the insert, because the webhook token is sealed bound to
 * it: `secret_sealed` is `v1:<keyId>:<iv>:<tag>:<ciphertext>`, an AES-256-GCM string whose additional
 * authenticated data is this row's id, so a sealed value copied to another row fails to open. The id
 * also rides in the webhook URL (`POST /v1/webhooks/{provider}/{id}`); it is NOT secret, the signature
 * is the authentication. The plaintext token exists only in API process memory while one delivery is
 * verified: it is never stored, returned or logged. Replacing it is ONE single-row update of
 * `secret_sealed` with a fresh IV, so a delivery verifying during the replacement sees the old or the
 * new token whole (P9).
 *
 * `provider` is a FORMAT, never an enum: the set of adapters is code, so a second gateway needs no
 * migration. One integration per tenant and provider (`unique (tenant_id, provider)`); two providers
 * in one tenant coexist (P3).
 *
 * RLS is enabled with **no policy at all**, deliberately, and `anon` / `authenticated` hold no table
 * privilege (the custom migration revokes them): the webhook route and the admin screens read and
 * write this table through the admin lane only (`packages/core/server/payments`). Adding a policy for
 * `authenticated` here is always a bug (SCHEMA-CONVENTIONS (i)): even a read policy would expose the
 * sealed token to a tenant lane. `supabase/tests/010` lists the table; `205` pins the zero count.
 */
export const paymentIntegrations = pgTable(
  'payment_integrations',
  {
    id: uuid().primaryKey().defaultRandom(),
    tenantId: uuid('tenant_id')
      .notNull()
      .references(() => tenants.id, { onDelete: 'cascade' }),
    provider: text().notNull(),
    /** `v1:<keyId>:<iv>:<tag>:<ciphertext>` (base64url). Never the plaintext token. */
    secretSealed: text('secret_sealed').notNull(),
    /** Which `PAYMENTS_SECRET_KEY_ID` sealed it (also inside the string), for rotation. */
    secretKeyId: smallint('secret_key_id').notNull().default(1),
    secretSetAt: timestamp('secret_set_at', { withTimezone: true }).notNull().defaultNow(),
    /** Advanced on a FIRST record of a delivery only; the Pagamentos card reads "recebido há X". */
    lastEventAt: timestamp('last_event_at', { withTimezone: true }),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    check('payment_integrations_provider_chk', sql`${t.provider} ~ '^[a-z][a-z0-9_]{1,30}$'`),
    // Tenant-first (the schema convention) and the arbiter of "one integration per provider".
    uniqueIndex('payment_integrations_tenant_provider_uq').on(t.tenantId, t.provider),
  ],
).enableRLS();
